import json,sys
d=json.load(sys.stdin)
for i in d['items']:
    for s in i.get('subjects') or []:
        if 'config' in s.get('name','') or 'reader' in s.get('name',''):
            print(i['kind'], i['metadata'].get('namespace'), i['metadata']['name'], '->', i['roleRef']['kind'], i['roleRef']['name'], s)
""}

